DROP TABLE IF EXISTS `employees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `employees` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `rank_id` bigint DEFAULT NULL,
  `sort_number` int DEFAULT NULL,
  `police_number` varchar(255) DEFAULT NULL,
  `insurance_number` varchar(255) DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `date_of_appointment` date DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `institute_id` bigint NOT NULL,
  `address` varchar(255) DEFAULT NULL,
  `age` int DEFAULT NULL,
  `alt_phone_number` varchar(255) DEFAULT NULL,
  `amen_or_ola` tinyint(1) NOT NULL,
  `bus` int NOT NULL,
  `date_of_edara` date DEFAULT NULL,
  `date_of_retirement` date DEFAULT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `dep_sort` int DEFAULT NULL,
  `department_id` bigint DEFAULT NULL,
  `district` varchar(100) DEFAULT NULL,
  `food` int NOT NULL,
  `gender` varchar(255) DEFAULT NULL,
  `governorate` varchar(100) DEFAULT NULL,
  `health_status` varchar(255) DEFAULT NULL,
  `id_number` varchar(14) DEFAULT NULL,
  `image` varchar(100) DEFAULT NULL,
  `mainornot` int NOT NULL,
  `marital_status` varchar(20) DEFAULT NULL,
  `nickname` varchar(255) DEFAULT NULL,
  `operation` varchar(20) DEFAULT NULL,
  `phone_number` varchar(255) DEFAULT NULL,
  `rahatcounter` int DEFAULT NULL,
  `rank_kind` int DEFAULT NULL,
  `tmamam` int NOT NULL,
  `total_leave` int DEFAULT NULL,
  `nots` longtext,
  `idcard_expir` date DEFAULT NULL,
  `idcard_social` varchar(20) DEFAULT NULL,
  `idcard_work` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `employees_id_number_36b22699_uniq` (`id_number`),
  KEY `employees_institute_id_7ce3b6c9_fk_institutes_institute_id` (`institute_id`),
  KEY `employees_department_id_e0a596e3_fk_departments_id` (`department_id`),
  KEY `employees_rank_id_ecfb75de` (`rank_id`),
  CONSTRAINT `employees_department_id_e0a596e3_fk_departments_id` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`),
  CONSTRAINT `employees_institute_id_7ce3b6c9_fk_institutes_institute_id` FOREIGN KEY (`institute_id`) REFERENCES `institutes_institute` (`id`),
  CONSTRAINT `employees_rank_id_ecfb75de_fk_ranks_rank_id` FOREIGN KEY (`rank_id`) REFERENCES `ranks_rank` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=239 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
